<?php require_once '../includes/auth.php';require_login();verify_csrf();$u=user();$title=trim($_POST['title']??'');$ref=strtoupper(trim($_POST['reference_number']??''));$cat=$_POST['category']??'other';$allowed=['ashram_shala','wastigruh','infrastructure','training','service','policy','other'];if($title===''||$ref===''||!in_array($cat,$allowed,true))exit('Invalid input');$code=strtoupper(trim($_POST['institution_code']??''));$it=$u['institution_type']??'';if(!is_admin())$code=$u['institution_code'];$in=trim($_POST['institution_name']??'');$v=trim($_POST['village']??'');$t=trim($_POST['taluka']??'');$d=trim($_POST['district']??'');$desc=trim($_POST['description']??'');$due=$_POST['due_date']??null;$s=mysqli_prepare($conn,"INSERT INTO records(title,reference_number,category,institution_type,institution_code,institution_name,village,taluka,district,status,description,owner_id,due_date) VALUES(?,?,?,?,?,?,?,?,?,'pending',?,?,?)");mysqli_stmt_bind_param($s,'ssssssssssis',$title,$ref,$cat,$it,$code,$in,$v,$t,$d,$desc,$u['id'],$due);mysqli_stmt_execute($s);log_activity('created','records',$title,mysqli_insert_id($conn));flash('success','Record created successfully.');redirect('list.php');
